-- Lead Desk · Display names and renaming products / sales engineers (6 Nov 2026)
-- Run once in Supabase → SQL Editor, after 13_upsell.sql. Safe to run again. No data is lost.
--
--  · Every user can set their own display name (shown in the app instead of their email).
--    Supervisors can change anyone's display name from Users and access.
--  · Supervisors (settings.manage) can rename a product or a sales engineer. The new name is written
--    everywhere the old one is used: leads (products, meetings, assigned to, generated by, preferred,
--    territory owner, upsell links), the product list, the engineer list, territories, the linked
--    login and the 2026 account history. One "Renamed" entry with the affected leads goes to the audit trail.

-- 1. Display name
alter table public.members add column if not exists display_name text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'members_display_name_len') then
    alter table public.members add constraint members_display_name_len check (display_name is null or char_length(display_name) between 1 and 60);
  end if;
end $$;

create or replace function public.set_my_display_name(p_name text) returns text
language plpgsql security definer set search_path = public as $$
declare v text := nullif(regexp_replace(trim(coalesce(p_name,'')), '\s+', ' ', 'g'), '');
begin
  if public.my_role() is null then raise exception 'Not signed in' using errcode = '42501'; end if;
  if v is not null and char_length(v) > 60 then raise exception 'Keep the name under 60 characters' using errcode = '22001'; end if;
  update public.members set display_name = v where email = public.my_email() and active;
  return v;
end $$;
revoke execute on function public.set_my_display_name(text) from public, anon;
grant execute on function public.set_my_display_name(text) to authenticated;

-- 2. Audit trigger can be paused inside one transaction (used only by the rename functions below)
create or replace function public.audit_row() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  w record; rec jsonb; old_j jsonb; new_j jsonb; ch jsonb; ent text := tg_argv[0]; rid text; act text; summ text; label text;
  noise text[] := array['log','updatedAt','assignedMailFor','followUpRemindedFor','updated_at','added_at'];
begin
  -- a bulk rename writes one summary entry instead of one per row
  if coalesce(current_setting('leaddesk.skip_audit', true),'') = 'on' then return null; end if;
  rec := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  rid := rec->>tg_argv[1];
  if tg_table_name in ('leads','accounts','docs') then
    old_j := case when tg_op <> 'INSERT' then to_jsonb(old)->'doc' end;
    new_j := case when tg_op <> 'DELETE' then to_jsonb(new)->'doc' end;
  else
    old_j := case when tg_op <> 'INSERT' then to_jsonb(old) end;
    new_j := case when tg_op <> 'DELETE' then to_jsonb(new) end;
  end if;
  if tg_table_name = 'docs' then
    ent := case rid when 'config/permissions' then 'permissions' when 'config/settings' then 'settings' else 'document' end;
  end if;
  ch := public.audit_diff(old_j, new_j, noise);
  if tg_op = 'UPDATE' and ch = '{}'::jsonb then return null; end if;   -- nothing meaningful changed
  act := case tg_op when 'INSERT' then 'created' when 'UPDATE' then 'updated' else 'deleted' end;
  label := coalesce(new_j->>'accountName', old_j->>'accountName', new_j->>'name', old_j->>'name', '');
  if tg_table_name = 'accounts' and coalesce((new_j->>'deleted')::boolean,false) and not coalesce((old_j->>'deleted')::boolean,false) then
    act := case when new_j ? 'mergedInto' then 'merged' else 'deleted' end;
  end if;
  -- leads are soft-deleted: show it as Deleted / Restored, with the reason, instead of a plain update
  if tg_table_name = 'leads' and tg_op = 'UPDATE' then
    if (new_j->>'deleted') is not null and (old_j->>'deleted') is null then act := 'deleted';
    elsif (new_j->>'deleted') is null and (old_j->>'deleted') is not null then act := 'restored';
    end if;
  end if;
  summ := initcap(act) || ' ' || ent || ' ' || coalesce(rid,'') || case when label <> '' then ' · ' || label else '' end;
  if tg_op = 'UPDATE' then
    summ := summ || ': ' || (select string_agg(k, ', ' order by k) from jsonb_object_keys(ch) k);
    if ch ? 'status' then summ := summ || ' (status ' || coalesce(ch->'status'->>'old','—') || ' → ' || coalesce(ch->'status'->>'new','—') || ')'; end if;
    if act = 'deleted' then summ := summ || ' · reason: ' || coalesce(new_j->'deleted'->>'reason','—')
       || case when coalesce(new_j->'deleted'->>'note','') <> '' then ' (' || (new_j->'deleted'->>'note') || ')' else '' end; end if;
    if ch ? 'assignedTo' then summ := summ || ' (assigned ' || coalesce(nullif(ch->'assignedTo'->>'old',''),'nobody') || ' → ' || coalesce(nullif(ch->'assignedTo'->>'new',''),'nobody') || ')'; end if;
  end if;
  select * into w from public.audit_who();
  insert into public.audit_log(actor, actor_role, source, action, entity, entity_id, summary, changes)
  values (w.actor, w.actor_role, w.source, act, ent, rid, summ, case when tg_op = 'UPDATE' then ch else null end);
  return null;
end $$;

-- 3. Rename helpers
create or replace function public.ld_same(a text, b text) returns boolean language sql immutable as $$
  select lower(regexp_replace(trim(coalesce(a,'')), '\s+', ' ', 'g')) = lower(regexp_replace(trim(coalesce(b,'')), '\s+', ' ', 'g'))
$$;

-- product names inside one lead
create or replace function public.ld_ren_product_doc(d jsonb, o text, n text) returns jsonb language plpgsql immutable as $$
declare ps jsonb; ms jsonb;
begin
  if jsonb_typeof(d->'products') = 'array' then
    select coalesce(jsonb_agg(case when public.ld_same(e, o) then to_jsonb(n) else to_jsonb(e) end order by i), '[]'::jsonb)
      into ps from jsonb_array_elements_text(d->'products') with ordinality t(e, i);
    d := jsonb_set(d, '{products}', ps);
    if jsonb_array_length(ps) > 0 then
      d := jsonb_set(d, '{product}', to_jsonb((select string_agg(e, ', ' order by i) from jsonb_array_elements_text(ps) with ordinality t(e, i))));
    end if;
  elsif public.ld_same(d->>'product', o) then
    d := jsonb_set(d, '{product}', to_jsonb(n));
  end if;
  if jsonb_typeof(d->'meetings') = 'array' then
    select jsonb_agg(case when jsonb_typeof(m->'products') = 'array' then jsonb_set(m, '{products}',
             (select coalesce(jsonb_agg(case when public.ld_same(e, o) then to_jsonb(n) else to_jsonb(e) end order by j), '[]'::jsonb)
                from jsonb_array_elements_text(m->'products') with ordinality u(e, j))) else m end order by i)
      into ms from jsonb_array_elements(d->'meetings') with ordinality t(m, i);
    d := jsonb_set(d, '{meetings}', coalesce(ms, '[]'::jsonb));
  end if;
  return d;
end $$;

-- engineer names inside one lead
create or replace function public.ld_ren_engineer_doc(d jsonb, o text, n text) returns jsonb language plpgsql immutable as $$
declare k text; ms jsonb;
begin
  foreach k in array array['assignedTo','generatedBy','formerAssignee','preferred','territoryOwner','originalGenerator'] loop
    if public.ld_same(d->>k, o) and coalesce(d->>k,'') <> '' then d := jsonb_set(d, array[k], to_jsonb(n)); end if;
  end loop;
  if jsonb_typeof(d->'meetings') = 'array' then
    select jsonb_agg(case when public.ld_same(m->>'by', o) and coalesce(m->>'by','') <> '' then jsonb_set(m, '{by}', to_jsonb(n)) else m end order by i)
      into ms from jsonb_array_elements(d->'meetings') with ordinality t(m, i);
    d := jsonb_set(d, '{meetings}', coalesce(ms, '[]'::jsonb));
  end if;
  if public.ld_same(d#>>'{upsellMeeting,by}', o) and coalesce(d#>>'{upsellMeeting,by}','') <> '' then
    d := jsonb_set(d, '{upsellMeeting,by}', to_jsonb(n));
  end if;
  return d;
end $$;

-- 2026 account history (registry): product keys, or the engineer recorded against each product
create or replace function public.ld_ren_registry(d jsonb, kind text, o text, n text) returns jsonb language sql immutable as $$
  select case when jsonb_typeof(d->'a') <> 'object' then d else jsonb_set(d, '{a}', coalesce((
    select jsonb_object_agg(acc, case when jsonb_typeof(v->'p') <> 'object' then v else jsonb_set(v, '{p}', coalesce((
      select jsonb_object_agg(case when kind = 'product' and public.ld_same(pk, o) then n else pk end,
                              case when kind = 'engineer' and jsonb_typeof(pv) = 'object' and public.ld_same(pv->>'e', o) then jsonb_set(pv, '{e}', to_jsonb(n)) else pv end)
      from jsonb_each(v->'p') p(pk, pv)), '{}'::jsonb)) end)
    from jsonb_each(d->'a') a(acc, v)), '{}'::jsonb)) end
$$;

-- names in a settings list (strings or {name: …} objects)
create or replace function public.ld_ren_list(l jsonb, o text, n text) returns jsonb language sql immutable as $$
  select case when jsonb_typeof(l) <> 'array' then l else coalesce((select jsonb_agg(
    case when jsonb_typeof(e) = 'string' and public.ld_same(e#>>'{}', o) then to_jsonb(n)
         when jsonb_typeof(e) = 'object' and public.ld_same(e->>'name', o) then jsonb_set(e, '{name}', to_jsonb(n))
         else e end order by i) from jsonb_array_elements(l) with ordinality t(e, i)), '[]'::jsonb) end
$$;

-- 4. Rename a product or a sales engineer everywhere (Supervisor)
create or replace function public.rename_everywhere(p_kind text, p_old text, p_new text) returns integer
language plpgsql security definer set search_path = public as $$
declare o text := trim(coalesce(p_old,'')); n text := regexp_replace(trim(coalesce(p_new,'')), '\s+', ' ', 'g');
        st jsonb; lst jsonb; ids text[]; cnt int; w record;
begin
  if not public.has_perm('settings.manage') then raise exception 'Only a Supervisor can rename products and engineers.' using errcode = '42501'; end if;
  if p_kind not in ('product','engineer') then raise exception 'Unknown kind %', p_kind; end if;
  if o = '' or n = '' then raise exception 'Enter the new name.' using errcode = '22023'; end if;
  if char_length(n) > 80 then raise exception 'Keep the name under 80 characters.' using errcode = '22001'; end if;
  select doc into st from public.docs where path = 'config/settings' for update;
  lst := st->(case p_kind when 'product' then 'products' else 'salespeople' end);
  if not public.ld_same(o, n) and exists (select 1 from jsonb_array_elements(coalesce(lst,'[]'::jsonb)) e
       where public.ld_same(case when jsonb_typeof(e) = 'string' then e#>>'{}' else e->>'name' end, n)) then
    raise exception '"%" already exists. Choose a different name.', n using errcode = '23505';
  end if;

  perform set_config('leaddesk.skip_audit', 'on', true);

  if p_kind = 'product' then
    with u as (update public.leads l set doc = public.ld_ren_product_doc(l.doc, o, n)
               where public.ld_ren_product_doc(l.doc, o, n) is distinct from l.doc returning l.id)
    select array_agg(id order by id) into ids from u;
    update public.docs set doc = jsonb_set(doc, '{products}', public.ld_ren_list(doc->'products', o, n)) where path = 'config/settings' and doc ? 'products';
  else
    with u as (update public.leads l set doc = public.ld_ren_engineer_doc(l.doc, o, n)
               where public.ld_ren_engineer_doc(l.doc, o, n) is distinct from l.doc returning l.id)
    select array_agg(id order by id) into ids from u;
    update public.docs set doc = jsonb_set(doc, '{salespeople}', public.ld_ren_list(doc->'salespeople', o, n)) where path = 'config/settings' and doc ? 'salespeople';
    update public.docs set doc = jsonb_set(doc, '{territories}', coalesce((select jsonb_agg(case when public.ld_same(t->>'engineer', o) then jsonb_set(t, '{engineer}', to_jsonb(n)) else t end order by i)
             from jsonb_array_elements(doc->'territories') with ordinality x(t, i)), '[]'::jsonb))
     where path = 'config/settings' and jsonb_typeof(doc->'territories') = 'array';
    update public.members set engineer = n where public.ld_same(engineer, o) and coalesce(engineer,'') <> '';
  end if;
  update public.docs set doc = public.ld_ren_registry(doc, p_kind, o, n)
   where path like 'registry/%' and public.ld_ren_registry(doc, p_kind, o, n) is distinct from doc;

  perform set_config('leaddesk.skip_audit', 'off', true);
  cnt := coalesce(array_length(ids, 1), 0);
  select * into w from public.audit_who();
  insert into public.audit_log(actor, actor_role, source, action, entity, entity_id, summary, changes)
  values (w.actor, w.actor_role, w.source, 'renamed', 'settings', p_kind,
          'Renamed ' || p_kind || ' "' || o || '" to "' || n || '" on ' || cnt || ' lead(s)',
          jsonb_build_object('name', jsonb_build_object('old', o, 'new', n), 'leads', jsonb_build_object('old', null, 'new', to_jsonb(coalesce(ids, '{}'::text[])))));
  return cnt;
end $$;
revoke execute on function public.rename_everywhere(text, text, text) from public, anon;
grant execute on function public.rename_everywhere(text, text, text) to authenticated;

-- Check
select count(*) filter (where display_name is not null) as users_with_display_name, count(*) as users from public.members;
